"""Writes Myna/Theme/VFD/VFDGlyphs.swift: the three glyph sizes as
[UInt32 scalar: [UInt32 rows]], bit 0 = leftmost pixel."""

from pathlib import Path

from font import SIZES, cached, chars

OUT = Path(__file__).resolve().parents[2] / "Myna" / "Theme" / "VFD" / "VFDGlyphs.swift"


def rows_of(bits) -> list[int]:
    return [sum(1 << x for x, on in enumerate(row) if on) for row in bits]


def main() -> None:
    lines = [
        "// Generated by tools/vfd/make_swift.py from tools/vfd/glyphs.py. Do not edit by hand.",
        "// An original 5x7 dot-matrix font; mid and big are Scale2x / Scale3x of it.",
        "// Each glyph: one UInt32 per row, top to bottom, bit 0 = leftmost pixel.",
        "",
        "enum VFDGlyphs {",
    ]
    for size, (scale, advance) in SIZES.items():
        lines.append(f"    /// {5 * scale}x{7 * scale} pixels (+{2 * scale} descender rows), {advance}-cell advance.")
        lines.append(f"    static let {size}: [UInt32: [UInt32]] = [")
        for ch in chars():
            rows = rows_of(cached(ch, size))
            text = ", ".join(f"0x{r:X}" for r in rows)
            lines.append(f"        0x{ord(ch):X}: [{text}],")
        lines.append("    ]")
        lines.append("")
    lines.append("}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote", OUT, OUT.stat().st_size, "bytes")


if __name__ == "__main__":
    main()
